import re
_RE = re.compile('[^\u0009\u000A\u000D\u0020-\uD7FF\uE000-\uFFFD\U00010000-\U0010FFFF]')
def rcc(b):
    if isinstance(b,str): return _RE.sub('',b)
    raw=bytes(b)
    t=raw.decode('utf-8',errors='surrogatepass')
    return _RE.sub('',t).encode('utf-8',errors='surrogatepass')

print('--- test_non_utf8_bytes_do_not_raise ---')
try:
    out = rcc('café'.encode('latin-1'))
    print('PASS', out)
except Exception as e:
    print('FAIL ->', type(e).__name__, ':', e)

print()
print('--- surrogatepass vs surrogateescape on arbitrary bytes ---')
for err in ('surrogatepass','surrogateescape'):
