import re
from lxml import etree

_RE = re.compile('[^\u0009\u000A\u000D\u0020-\uD7FF\uE000-\uFFFD\U00010000-\U0010FFFF]')

def new_rcc(byte_node):
    if isinstance(byte_node, str):
        return _RE.sub('', byte_node)
    if isinstance(byte_node, (bytes, bytearray, memoryview)):
        raw = bytes(byte_node)
        t = raw.decode('utf-8', errors='surrogatepass')
        return _RE.sub('', t).encode('utf-8', errors='surrogatepass')
    raise TypeError('bad')

_old = re.compile('[^\u0009\u000A\u000D\u0020-\uD7FF\uE000-\uFFFD\U00010000-\U0010FFFF]'.encode())
def old_rcc(b): return _old.sub(b'', b)

# Realistic: latin-1 / windows-1252 encoded XML from a partner EDI feed
payload = '<?xml version=\"1.0\" encoding=\"ISO-8859-1\"?><Inv><Party>Soci\xe9t\xe9 G\xe9n\xe9rale</Party></Inv>'.encode('latin-1')
print('payload:', payload[:60], '...')
print()
parser = etree.XMLParser(recover=True, resolve_entities=False)

print('== OLD (base 19.0) ==')
try:
    n = etree.fromstring(old_rcc(payload), parser=parser)
    print('  OK ->', etree.tostring(n))
except Exception as e:
    print('  RAISE', type(e).__name__, e)

print('== NEW (this PR) ==')
try:
    n = etree.fromstring(new_rcc(payload), parser=parser)
    print('  OK ->', etree.tostring(n))
except Exception as e:
    print('  RAISE', type(e).__name__, ':', e)
""}

