import re
from lxml import etree
# Suggested fix: surrogateescape round-trip, and DON'T strip the escape surrogates
_ILLEGAL = re.compile('[^\u0009\u000A\u000D\u0020-\uD7FF\uE000-\uFFFD\U00010000-\U0010FFFF]')
_ILLEGAL_KEEP_SURR = re.compile('[^\u0009\u000A\u000D\u0020-\uD7FF\uDC80-\uDCFF\uE000-\uFFFD\U00010000-\U0010FFFF]')
def fixed(b):
    if isinstance(b,str): return _ILLEGAL.sub('',b)
    t=bytes(b).decode('utf-8',errors='surrogateescape')
    return _ILLEGAL_KEEP_SURR.sub('',t).encode('utf-8',errors='surrogateescape')
parser=etree.XMLParser(recover=True,resolve_entities=False)
cases={
 'latin1 EDI xml': '<?xml version=\"1.0\" encoding=\"ISO-8859-1\"?><Inv><P>Société</P></Inv>'.encode('latin-1'),
 'utf8 with U+FFFE': '<Inv><P>a\ufffeb\uffffc</P></Inv>'.encode('utf-8'),
 'utf8 with NUL':    '<Inv><P>a\x00b</P></Inv>'.encode('utf-8'),
}
for name,payload in cases.items():
    out=fixed(payload)
    print(name)
    print('   bytes out:', out[:80])
    try: print('   lxml ->', etree.tostring(etree.fromstring(out,parser=parser)))
    except Exception as ex: print('   RAISE',type(ex).__name__,ex)
print()
print('latin-1 bytes preserved byte-identical?', fixed('café'.encode('latin-1'))=='café'.encode('latin-1'))
""}

